WITH "__duckstream_0" AS (SELECT t.c0 AS c0, CAST(MIN(t.c1) AS DOUBLE) AS c1, CAST(MAX(t.c1) AS DOUBLE) AS c2, CAST(AVG(t.c1) AS DOUBLE) AS c3, CAST(MIN(t.c2) AS DECIMAL(18,2)) AS c4, CAST(MAX(t.c2) AS DECIMAL(18,2)) AS c5 FROM (SELECT "g" AS c0, "value" AS c1, "exact_value" AS c2 FROM "metrics") t GROUP BY t.c0)
SELECT CAST(result.c0 AS INTEGER) AS "g", CAST(result.c1 AS DOUBLE) AS "low", CAST(result.c2 AS DOUBLE) AS "high", CAST(result.c3 AS DOUBLE) AS "mean", CAST(result.c4 AS DECIMAL(18,2)) AS "exact_low", CAST(result.c5 AS DECIMAL(18,2)) AS "exact_high" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5 FROM "__duckstream_0" v) result;
